const body = $input.first().json.body ?? $input.first().json;
if (body.event && !/messages.upsert/i.test(body.event)) return [];
const d = body.data ?? {};
const key = d.key ?? {};
const jid = key.remoteJid ?? '';
if (key.fromMe || !jid || jid.endsWith('@broadcast')) return [];

const b64of = (x) => (x && typeof x === 'object' ? Buffer.from(Array.isArray(x) ? x : Object.keys(x).sort((a, b) => a - b).map((k) => x[k])).toString('base64') : typeof x === 'string' ? x : null);

// EDICIÓN de un mensaje: WhatsApp la manda cifrada (secretEncryptedMessage, tipo 2 = MESSAGE_EDIT). El hub la descifra con la clave del mensaje original.
const sec = d.message?.secretEncryptedMessage;
if (sec?.targetMessageKey?.id && (sec.secretEncType === 2 || sec.secretEncType === 'MESSAGE_EDIT') && sec.encPayload && sec.encIv) {
  const ed = { sessionId: jid, name: d.pushName || null, key: { id: key.id, remoteJid: jid }, instance: body.instance, kind: 'edit', text: '', quoted: null,
    edit: { targetId: sec.targetMessageKey.id, encPayload: b64of(sec.encPayload), encIv: b64of(sec.encIv), alt: key.remoteJidAlt ?? null } };
  if (jid.endsWith('@g.us')) { ed.participant = key.participant ?? d.participant ?? null; ed.botJid = body.sender ?? null; }
  return [{ json: ed }];
}

// desenvolver mensajes temporales, de ver una vez, editados y documentos con texto
let m = d.message ?? {};
const b64 = m.base64 ?? d.base64 ?? null; // si Evolution llegara a incluir el archivo en el webhook
const secret = b64of((d.message?.messageContextInfo ?? m.messageContextInfo)?.messageSecret); // clave del mensaje: permite descifrar sus futuras ediciones
for (let i = 0; i < 4; i++) {
  const inner = m.ephemeralMessage?.message ?? m.viewOnceMessage?.message ?? m.viewOnceMessageV2?.message ?? m.documentWithCaptionMessage?.message ?? m.editedMessage?.message ?? null;
  if (!inner) break;
  m = inner;
}

// mensaje citado (respuesta a otro mensaje). Evolution lo manda en data.contextInfo para textos simples,
// y dentro del mensaje (extendedTextMessage, imageMessage…) en otros casos.
const ctx = (m.extendedTextMessage ?? m.imageMessage ?? m.videoMessage ?? m.audioMessage ?? m.documentMessage ?? m.stickerMessage ?? {}).contextInfo ?? m.contextInfo ?? d.contextInfo ?? {};
const q = ctx.quotedMessage;
const quoted = q ? (q.conversation ?? q.extendedTextMessage?.text ?? q.imageMessage?.caption ?? q.videoMessage?.caption ?? q.documentMessage?.caption ?? q.documentWithCaptionMessage?.message?.documentMessage?.caption ?? (q.audioMessage ? '[nota de voz]' : q.imageMessage ? '[imagen]' : q.videoMessage ? '[video]' : q.documentMessage ? `[documento ${q.documentMessage.fileName ?? ''}]` : q.stickerMessage ? '[sticker]' : q.locationMessage ? '[ubicación]' : null)) : null;

const ev = { sessionId: jid, name: d.pushName || null, key: { id: key.id, remoteJid: jid }, instance: body.instance, kind: null, text: '', quoted, secret };
// grupos: quién escribió, a quién mencionaron / respondieron y cuál es la cuenta del agente (el hub decide si le hablan a él)
if (jid.endsWith('@g.us')) { ev.participant = key.participant ?? d.participant ?? null; ev.mentionedJid = ctx.mentionedJid ?? []; ev.quotedParticipant = ctx.participant ?? null; ev.botJid = body.sender ?? null; }
const vcardPhones = (v = '') => [...v.matchAll(/TEL[^:]*:([+\d\s().-]+)/g)].map((x) => x[1].trim());

if (m.conversation != null || m.extendedTextMessage) { ev.kind = 'text'; ev.text = m.conversation ?? m.extendedTextMessage.text ?? ''; }
else if (m.audioMessage) { ev.kind = 'audio'; ev.seconds = m.audioMessage.seconds; ev.mimetype = m.audioMessage.mimetype; }
else if (m.imageMessage) { ev.kind = 'image'; ev.text = m.imageMessage.caption ?? ''; ev.mimetype = m.imageMessage.mimetype; }
else if (m.videoMessage) { ev.kind = 'video'; ev.text = m.videoMessage.caption ?? ''; ev.seconds = m.videoMessage.seconds; ev.mimetype = m.videoMessage.mimetype; }
else if (m.documentMessage) { ev.kind = 'document'; ev.text = m.documentMessage.caption ?? ''; ev.fileName = m.documentMessage.fileName; ev.mimetype = m.documentMessage.mimetype; }
else if (m.locationMessage || m.liveLocationMessage) { const l = m.locationMessage ?? m.liveLocationMessage; ev.kind = 'location'; ev.location = { lat: l.degreesLatitude, lng: l.degreesLongitude, name: l.name, address: l.address }; }
else if (m.contactMessage) { ev.kind = 'contact'; ev.contact = { name: m.contactMessage.displayName, phones: vcardPhones(m.contactMessage.vcard) }; }
else if (m.contactsArrayMessage) { ev.kind = 'contact'; const cs = m.contactsArrayMessage.contacts ?? []; ev.contact = { name: cs.map((c) => c.displayName).join(', '), phones: cs.flatMap((c) => vcardPhones(c.vcard)) }; }
else if (m.stickerMessage) { ev.kind = 'sticker'; ev.mimetype = m.stickerMessage.mimetype; ev.animated = !!m.stickerMessage.isAnimated; }
else return []; // reacciones, protocolo, etc.

if (ev.kind === 'text' && !ev.text.trim()) return [];

// datos para bajar y descifrar el archivo (url de WhatsApp + mediaKey)
const MEDIA = ['audio', 'image', 'video', 'document', 'sticker'];
const mm = m.audioMessage ?? m.imageMessage ?? m.videoMessage ?? m.documentMessage ?? m.stickerMessage ?? null;
if (mm?.mediaKey && MEDIA.includes(ev.kind)) ev.media = { url: mm.url, directPath: mm.directPath, mediaKey: mm.mediaKey, mimetype: mm.mimetype, fileLength: mm.fileLength };
if (b64 && MEDIA.includes(ev.kind)) ev.base64 = b64;
return [{ json: ev }];

const r = $input.first().json;
const ev = $('Clasificar mensaje').first().json;
const number = ev.sessionId;
const base = { instance: ev.instance, replyTo: r.replyTo ?? ev.key?.id ?? null, msgId: r.msgId ?? null };
const items = [];

// 0) Corrección por edición: se EDITA el mensaje que el agente ya había enviado (no se manda uno nuevo)
if (r.edit?.key?.id && r.edit.text) {
  return [{ json: { ...base, endpoint: 'updateMessage', path: '/chat/updateMessage', body: { number, key: r.edit.key, text: r.edit.text } } }];
}

// 1) Texto: partir por párrafos y agrupar en mensajes de ~600 caracteres (máximo 4), como escribiría una persona
const text = String(r.reply ?? '').trim();
if (text) {
  const paras = text.split(/\n{2,}/).map((s) => s.trim()).filter(Boolean);
  const chunks = [];
  let cur = '';
  for (const p of paras) {
    if (cur && cur.length + p.length > 600) { chunks.push(cur); cur = p; }
    else cur = cur ? cur + '\n\n' + p : p;
  }
  if (cur) chunks.push(cur);
  while (chunks.length > 4) { const last = chunks.pop(); chunks[chunks.length - 1] += '\n\n' + last; }
  // si el agente decidió citar un mensaje (función "responder" de WhatsApp), solo el primer mensaje lleva la cita
  chunks.forEach((t, i) => items.push({ json: { ...base, endpoint: 'sendText', body: { number, text: t, delay: i === 0 ? 600 : Math.min(2500, 700 + t.length * 12), ...(i === 0 && r.quote ? { quoted: r.quote } : {}) } } }));
}

// 2) Archivos adjuntos (después del texto): notas de voz como audio, el resto como imagen/video/documento
for (const a of (r.attachments ?? []).slice(0, 5)) {
  if (a.mediatype === 'audio') items.push({ json: { ...base, endpoint: 'sendWhatsAppAudio', body: { number, audio: a.url, delay: 1200 } } });
  else items.push({ json: { ...base, endpoint: 'sendMedia', body: { number, mediatype: a.mediatype, mimetype: a.mimetype, caption: a.caption || '', media: a.url, fileName: a.fileName, delay: 1000 } } });
}
return items;

// Se ejecuta solo cuando Evolution/WhatsApp rechaza un envío: le contamos a la persona qué pasó.
const prep = $('Preparar envíos').all();
const out = [];
for (const it of $input.all()) {
  const orig = prep[it.pairedItem?.item ?? 0]?.json ?? {};
  if (orig.endpoint === 'sendText' || orig.endpoint === 'updateMessage') continue; // si falla el texto o la edición no hay forma (ni sentido) de avisar
  const b = orig.body ?? {};
  const raw = String(it.json?.error?.message ?? it.json?.error?.description ?? it.json?.message ?? '');
  const code = String(it.json?.error?.httpCode ?? it.json?.error?.status ?? '');
  let why;
  if (/413|too large|entity too large|payload/i.test(raw + code)) why = 'es demasiado pesado para que WhatsApp lo acepte';
  else if (/timeout|timed out|ETIMEDOUT|ECONNABORTED/i.test(raw)) why = 'tardó demasiado en subirse a WhatsApp';
  else if (/ECONNREFUSED|ENOTFOUND|socket|fetch|Request failed with status code (403|404)/i.test(raw)) why = 'WhatsApp no pudo descargar el archivo desde mi servidor';
  else if (/mimetype|media|unsupported|invalid/i.test(raw)) why = 'WhatsApp no aceptó ese tipo de archivo';
  else why = raw.slice(0, 140) || 'WhatsApp lo rechazó sin dar más detalles';
  const name = b.fileName ? `«${b.fileName}»` : 'el archivo';
  out.push({ json: { instance: orig.instance, endpoint: 'sendText', body: { number: b.number, text: `Preparé ${name} pero no pude enviarlo: ${why}. ¿Querés que pruebe de otra forma (otro formato, más liviano, o te paso el enlace)?`, delay: 600 } } });
}
return out;

// ids de WhatsApp de los mensajes que se enviaron OK (para poder citarlos o editarlos después)
const prep = $('Preparar envíos').all();
const first = prep[0]?.json ?? {};
const ids = $input.all().map((i) => i.json?.key?.id).filter(Boolean);
if (!ids.length || !first.msgId) return [];
return [{ json: { jid: first.body?.number, instance: first.instance, msgId: first.msgId, replyTo: first.replyTo, ids } }];
